        <h2>Панель «Параметры хранения веб-сайтов»</h2>
		<div id="infolocal" class="swfcontent"><embed type="application/x-shockwave-flash" src="http://www.macromedia.com/support/flashplayer/sys/settingsmanager.swf" width="395" height="270" id="infolocal_swf" name="infolocal_swf" bgcolor="#ffffff" quality="high" scale="noscale" wmode="opaque" flashvars="defaultTab=localinformation"></div>
<script type="text/javascript">
   // <![CDATA[
    if (top!=self){
        top.location.href=self.location.href;
    }
    var props = new Object();
    props.swf = "http://www.macromedia.com/support/flashplayer/sys/settingsmanager.swf";
    props.id = "infolocal_swf";
    props.ver = "6";
    props.w = "395";
    props.h = "270";
    props.c = "#ffffff";
    props.wmode= "opaque";
	props.scale = "noscale";
